import { CommentsOptions, ContainersList, CommentsCreate, CommentsDelete, CommentsUpdate } from '../types';

export class ApiClient {
  private baseUrl: string;
  //private apiKey:  string;
  
  constructor(baseUrl: string) {
    this.baseUrl = baseUrl.trim().replace(/^['\"]|['\"]$/g, '').replace(/\/$/, '');
    //this.apiKey  = apiKey;
  }

  private async request<T>(path: string, options: RequestInit = {}): Promise<T> {
    const response = await fetch(`${this.baseUrl}${path}`, {
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options.headers,
      },
    });

    if (!response.ok) {
      const err = await response.json().catch(() => ({ detail: 'Erro desconhecido' }));
      throw { status: response.status, data: err };
    }

    return response.json();
  }

  async getContainers(): Promise<ContainersList[]> {
    return this.request<ContainersList[]>('/containers',{
       method: 'GET'
    });
  }

  async getComments(): Promise<CommentsOptions[]> {
    return this.request<CommentsOptions[]>('/comments',{
      method: 'GET'
    });
  }

  async createComment(payload: CommentsCreate): Promise<{ cod_record: number; message: string }> {
    return this.request('/comments', {
      method: 'POST',
      body:   JSON.stringify(payload),
    });
  }

  async deleteComment(payload: CommentsDelete): Promise<{ cod_record: number; message: string }> {
    return this.request('/comments', {
      method: 'DELETE',
      body:   JSON.stringify(payload),
    });
  }

  async updateComment(payload: CommentsUpdate): Promise<{ cod_record: number; message: string }> {
    return this.request('/comments', {
      method: 'PATCH',
      body:   JSON.stringify(payload),
    });
  }
}