import { PanelPlugin } from '@grafana/data';
import { PluginOptions } from './types';
import { CommentsPanel } from './components/CommentsPanel';

export const plugin = new PanelPlugin<PluginOptions>(CommentsPanel).setPanelOptions((builder) => {
  builder
    .addTextInput({
      path:         'apiUrl',
      name:         'URL da API',
      description:  'Endereço da fmdfiltercount-api (ex: http://exceptions-api:8080)',
      defaultValue: 'http://10.113.120.120:8012/fmdfiltercount/api',
    })
    .addTextInput({
      path:        'apiKey',
      name:        'API Key',
      description: 'Token de autenticação configurado no servidor',
      defaultValue: '',
      settings:    { placeholder: 'Token secreto...' },
    });
});
