import React, { useState, useEffect } from 'react';
import { PanelProps } from '@grafana/data';
import { locationService } from '@grafana/runtime';
import { PluginOptions, CommentsOptions, ContainersList, CommentsCreate, CommentsDelete } from '../types';
import { ApiClient } from '../api/client';
import { CommentsModal } from './CommentsModal';

interface Props extends PanelProps<PluginOptions> {}

export const CommentsPanel: React.FC<Props> = ({ options }) => {
  const client = new ApiClient(options.apiUrl);
  const [showModal, setShowModal] = useState(false);
  const [comments, setComments] = useState<CommentsOptions[]>([]);
  const [containers, setContainers] = useState<ContainersList[]>([]);
  const [modalLoading, setModalLoading] = useState(false);
  const [modalLoadingDelete, setModalLoadingDelete] = useState(false);
  const [modalDelete, setModalDelete] = useState(true);
  const [modalError, setModalError] = useState<string | null>(null);
  const [modalSuccess, setModalSuccess] = useState(false);
  const [modalDeleteSuccess, setModalDeleteSuccess] = useState(false);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [isLoadingData, setIsLoadingData] = useState(true);

  useEffect(() => {
    setIsLoadingData(true);
    setLoadError(null);
    client.getComments()
      .then(setComments)
      .catch((e: any) => setLoadError(e?.data?.detail || e?.message || 'Erro ao carregar comentarios'))
      .finally(() => setIsLoadingData(false));
  }, [options.apiUrl]);

  useEffect(() => {
    setIsLoadingData(true);
    setLoadError(null);
    client.getContainers()
      .then(setContainers)
      .catch((e: any) => setLoadError(e?.data?.detail || e?.message || 'Erro ao carregar conteineres'))
      .finally(() => setIsLoadingData(false));
  }, [options.apiUrl]);

  const updateContainersList = (rank: number, cod_id: number, nam_comments: string | null) => {
    setContainers(items => items.map(item => item.Rank === rank ? { ...item, cod_id, nam_comments } : item));
  };

  const handleSubmit = async (payload: CommentsCreate) => {
    setModalLoading(true);
    setModalError(null);
    try {
      if (payload.cod_id > 0) {
        await client.updateComment(payload);
        updateContainersList(payload.Rank, payload.cod_id, payload.nam_comments);
      } else {
        const response = await client.createComment(payload);
        updateContainersList(payload.Rank, response.cod_record, payload.nam_comments);
      }
      setModalSuccess(true);
      locationService.partial({ 'var-varupdate': Date.now().toString() }, true);
      setTimeout(() => {
        setShowModal(false);
        setModalSuccess(false);
      }, 1500);
    } catch (err: any) {
      const detail = err?.data?.detail;
      setModalError(typeof detail === 'string' ? detail : 'Erro ao registrar comentario');
    } finally {
      setModalLoading(false);
    }
  };

  const handleDelete = async (payload: CommentsDelete) => {
    setModalLoadingDelete(true);
    setModalError(null);
    try {
      await client.deleteComment(payload);
      updateContainersList(payload.Rank, 0, '');
      setModalDeleteSuccess(true);
      locationService.partial({ 'var-varupdate': Date.now().toString() }, true);
      setTimeout(() => {
        setShowModal(false);
        setModalDeleteSuccess(false);
      }, 1500);
    } catch (err: any) {
      const detail = err?.data?.detail;
      setModalError(typeof detail === 'string' ? detail : 'Erro ao excluir comentario');
    } finally {
      setModalLoadingDelete(false);
    }
  };

  const showButtonDelete = (payload: boolean) => {
    setModalError(null);
    setModalDelete(payload);
  };

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <span style={styles.title}>⚡ Comentários Contêineres</span>
        <button
          type="button"
          style={styles.openBtn}
          onClick={() => {
            setModalError(null);
            setModalSuccess(false);
            setModalDeleteSuccess(false);
            setModalDelete(true);
            setShowModal(true);
          }}
        >
          Gerir Comentários
        </button>
      </div>

      {isLoadingData && <div style={styles.infoBox}>Carregando dados...</div>}
      {loadError && <div style={styles.errorBox}>{loadError}</div>}
      {!isLoadingData && !loadError && (
        <div style={styles.infoBox}>
          Comentarios carregados: {comments.length} | Conteineres carregados: {containers.length}
        </div>
      )}

      {showModal && (
        <CommentsModal
          comments={comments}
          containers={containers}
          onSubmit={handleSubmit}
          onDelete={handleDelete}
          onClose={() => setShowModal(false)}
          onChangeContainer={showButtonDelete}
          isLoading={modalLoading}
          isDelete={modalDelete}
          error={modalError}
          success={modalSuccess}
          deletesuccess={modalDeleteSuccess}
          isLoadingDelete={modalLoadingDelete}
        />
      )}
    </div>
  );
};

const styles: Record<string, React.CSSProperties> = {
  container: {
    padding: 12,
    height: '100%',
    display: 'flex',
    flexDirection: 'column',
    gap: 12,
    overflow: 'hidden',
  },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  title: {
    color: '#e0e0e0',
    fontWeight: 700,
    fontSize: 14,
  },
  openBtn: {
    backgroundColor: '#2e75b6',
    border: 'none',
    borderRadius: 4,
    color: '#fff',
    padding: '7px 14px',
    fontSize: 13,
    fontWeight: 600,
    cursor: 'pointer',
  },
  infoBox: {
    backgroundColor: '#111827',
    border: '1px solid #374151',
    borderRadius: 4,
    color: '#d1d5db',
    padding: '8px 10px',
    fontSize: 12,
  },
  errorBox: {
    backgroundColor: '#3a1a1a',
    border: '1px solid #c0392b',
    borderRadius: 4,
    color: '#e74c3c',
    padding: '8px 10px',
    fontSize: 12,
  },
};
