import React, { useState, useEffect, useMemo,  } from 'react';
import { Modal } from '@grafana/ui';
import { CommentsOptions, ContainersList, CommentsDelete, CommentsCreate } from '../types';

interface Props {
  comments:           CommentsOptions[];
  containers:         ContainersList[];
  onSubmit:           (payload: CommentsCreate) => Promise<void>;
  onClose:            () => void;
  onChangeContainer:  (payload: boolean) => void;
  onDelete:           (payload: CommentsDelete) => Promise<void>;
  isLoading:          boolean;
  isLoadingDelete:    boolean;
  isDelete:           boolean;
  error:              string | null;
  success:            boolean;
  deletesuccess:      boolean;  
}

export const CommentsModal: React.FC<Props> = ({
  comments, containers, onDelete, onSubmit, onClose, isLoading, isDelete, error, success, deletesuccess,  onChangeContainer, isLoadingDelete
}) => {

  const containerOptions = useMemo(
    () => containers.map(cnt => ({ container: cnt.container, comment: cnt.nam_comments, id: cnt.cod_id, Rank: cnt.Rank, srcproductno: cnt.srcproductno })),
    [containers]
  );

  const commentOptions = useMemo(
    () => comments.map(cmt => ({ type: cmt.nam_comments_type, comment: cmt.nam_comments })),
    [comments]
  );
    
  const [isDisableConfirm, setIsDisableConfirm]    = useState(true);

  const [form, setForm] = useState({
    Rank: 0,
    val_container_number: '', //containers[0]?.container ?? 0
    nam_comments: '', //comments[0]?.nam_comments ?? 0
    cod_id: 0, //containers[0]?.cod_id ?? 0
  });

  useEffect(() => {
    if (containers.length > 0 && form.val_container_number === null) {
      setForm(f => ({ ...f, val_container_number: containers[0].container, cod_id: containers[0].cod_id, Rank: containers[0].Rank }));
    }
  }, [containers, form.val_container_number]);

  useEffect(() => {
    if (comments.length > 0 && form.nam_comments === null) {
      setForm(f => ({ ...f, nam_comments: comments[0].nam_comments }));
    }
  }, [comments, form.nam_comments]);

  const handleSubmit = () => {
    onSubmit({
      cod_id:               form.cod_id,
      Rank:                 form.Rank,
      val_container_number: form.val_container_number,
      nam_comments_type:    'DSH',
      nam_comments:         form.nam_comments,
      usr_grafana:          'grafana',
    });
  };

  const handleDelete = () => {
    onDelete({
      cod_id: form.cod_id,
      Rank:   form.Rank,
    });
  };

  const showButtonDelete = (playload: boolean, actualcomment: string) => {
    onChangeContainer(playload);
    setForm(f => ({
      ...f,
      nam_comments: actualcomment,
    }));
  };

  useEffect(() => {
    console.log(form.nam_comments.trim())
    console.log(form.val_container_number.trim())
    console.log(form.Rank)
    if (form.nam_comments.trim() === '' || form.val_container_number.trim() === '') {
      setIsDisableConfirm(true)
    } else {
      setIsDisableConfirm(false)
    }
  },[form]);

  const modal = (
    <Modal title="Registrar/Excluir Comentários" isOpen={true} onDismiss={onClose}>
      <div className="bat-comments-modal">
        <style>{`
          .bat-comments-modal .bat-native-select {
            width: 100%;
            min-height: 40px;
            background: #111217 !important;
            border: 1px solid #333 !important;
            border-radius: 4px;
            padding: 10px 12px;
            box-sizing: border-box;
            color: #e8edf2 !important;
            -webkit-text-fill-color: #e8edf2 !important;
            appearance: auto;
          }
          .bat-comments-modal .bat-native-select option {
            color: #e8edf2 !important;
            background: #151a21 !important;
          }
          .bat-comments-modal .bat-selected-chip {
            margin-top: 6px;
            color: #a8b7c7;
            font-size: 12px;
          }
        `}</style>

        <div style={styles.body}>

          {/* Contêineres */}
          <label style={styles.label}>Contêineres *</label>
          <select
            className="bat-native-select"
            onChange={
                e =>{
                    const selectedOption = Number(e.target.selectedOptions[0].getAttribute('custom-key'));
                    const selectedRank = Number(e.target.selectedOptions[0].getAttribute('custom-rank'));
                    setForm(f => ({ ...f, val_container_number: e.target.value, cod_id: selectedOption, Rank: selectedRank}));
                    console.log(Number(e.target.selectedOptions[0].getAttribute('custom-key')));
                    if (selectedOption === 0 || selectedOption === null) {
                      showButtonDelete(true, '')
                    } else {
                      showButtonDelete(false, String(e.target.selectedOptions[0].getAttribute('custom-comment')))
                    };
                    }
            }
          >
            <option value="" disabled selected>Selecione um contêiner</option>
            {containerOptions.map(o => <option key={o.id} custom-key={o.id} custom-comment={o.comment} custom-rank={o.Rank} value={o.container}>[{o.Rank}] {o.container}</option>)}
          </select>
          <div className="bat-selected-chip">Selecionado: {form.val_container_number || '---'}</div>

          {/* Comentário */}
          <label style={styles.label}>Comentário *</label>
          <select
            className="bat-native-select"
            value={String(form.nam_comments)}
            
            onChange={e => setForm(f => ({ ...f, nam_comments: e.target.value }))}
          >
            <option value="" disabled>Selecione um comentário</option>
            {commentOptions.map(o => <option key={String(o.comment)} value={String(o.comment)}>{o.comment}</option>)}
          </select>
          <div className="bat-selected-chip">
            Selecionado: {commentOptions.find(o => o.comment === form.nam_comments)?.comment || '---'}
          </div>

          {/* Erro */}
          {error && (
            <div style={styles.errorBox}>
              {error}
            </div>
          )}

          {/* Sucesso */}
          {success && (
            <div style={styles.successBox}>
              Comentário registrado com sucesso
            </div>
          )}

          {/* Delete */}
          {deletesuccess && (
            <div style={styles.successBox}>
              Comentário excluído com sucesso
            </div>
          )}
        </div>

        <div style={styles.footer}>
          <button style={styles.cancelBtn} onClick={onClose} disabled={isLoading}>
            Cancelar
          </button>
          <button style={styles.deleteBtn} onClick={handleDelete} disabled={isLoadingDelete || deletesuccess} hidden={isDelete}>
            {isLoadingDelete ? 'Excluindo...' : 'Excluir'}
          </button>
          <button style={ isDisableConfirm==false ? styles.confirmBtn: styles.isDisableConfirm } onClick={handleSubmit} disabled={isLoading || success || isDisableConfirm}>
            {isLoading ? 'Gravando...' : 'Confirmar'}
          </button>
        </div>
      </div>
    </Modal>
  );

  return modal;
};

const styles: Record<string, React.CSSProperties> = {
  body: {
    padding:       '20px 22px',
    display:       'flex',
    flexDirection: 'column',
    gap:           10,
    overflowY:     'auto',
  },
  label: {
    color:    '#aaa',
    fontSize: 12,
    fontWeight: 600,
    margin:   0,
  },
  input: {
    width:           '100%',
    backgroundColor: '#111217',
    border:          '1px solid #333',
    borderRadius:    4,
    color:           '#e0e0e0',
    padding:         '10px 12px',
    minHeight:       40,
    fontSize:        14,
    WebkitTextFillColor: '#e0e0e0',
    boxSizing:       'border-box',
  },
  row: {
    display:   'flex',
    flexWrap:  'wrap',
    gap:       12,
    width:     '100%',
  },
  col: {
    flex:          1,
    minWidth:      250,
    display:       'flex',
    flexDirection: 'column',
    gap:           4,
  },
  errorBox: {
    backgroundColor: '#3a1a1a',
    border:          '1px solid #c0392b',
    borderRadius:    4,
    color:           '#e74c3c',
    padding:         '10px 12px',
    fontSize:        13,
  },
  successBox: {
    backgroundColor: '#1a3a1a',
    border:          '1px solid #27ae60',
    borderRadius:    4,
    color:           '#2ecc71',
    padding:         '10px 12px',
    fontSize:        13,
  },
  footer: {
    display:        'flex',
    justifyContent: 'flex-end',
    gap:            10,
    padding:        '14px 20px',
    borderTop:      '1px solid #2a2d33',
  },
  cancelBtn: {
    backgroundColor: 'transparent',
    border:          '1px solid #444',
    borderRadius:    4,
    color:           '#aaa',
    padding:         '8px 18px',
    fontSize:        13,
    cursor:          'pointer',
  },
  confirmBtn: {
    backgroundColor: '#2e75b6',
    border:          'none',
    borderRadius:    4,
    color:           '#fff',
    padding:         '8px 18px',
    fontSize:        13,
    fontWeight:      600,
    cursor:          'pointer',
  },
   disableBtn: {
    backgroundColor: '#A9A9A9',
    border:          'none',
    borderRadius:    4,
    color:           '#000',
    padding:         '8px 18px',
    fontSize:        13,
    fontWeight:      600,
    cursor:          'pointer',
  },
  deleteBtn: {
    backgroundColor:  '#F40022',
    border:          'none',
    borderRadius:    4,
    color:           '#fff',
    padding:         '8px 18px',
    fontSize:        13,
    fontWeight:      600,
    cursor:          'pointer',
  },
};
